arguments.command:
cd /workspace && python3 - << 'EOF'
import os
pid=os.fork()
if pid==0:
    print("child pid",os.getpid(),"pgid",os.getpgid(0),"sid",os.getsid(0), flush=True)
    try:
        os.setpgid(0,0); print("setpgid ok, now pgid",os.getpgid(0), flush=True)
    except OSError as e: print("setpgid fail",e, flush=True)
    try:
        os.setsid(); print("setsid ok", flush=True)
    except OSError as e: print("setsid fail",e, flush=True)
    os._exit(0)
os.waitpid(pid,0)
print("parent pid",os.getpid(),"pgid",os.getpgid(0),"sid",os.getsid(0))
EOF
